theorem sum_progressionMaxError_le_primary {Q X : ℕ}
    (hQ : Q ≤ primaryCutoff X ^ 2) :
    (∑ q ∈ Icc 1 Q, progressionMaxError (2 * X + 2) q) ≤ primaryProgressionError X

theorem eventually_abs_sub_mul_le_of_tendsto_div (f : ℕ → ℝ) {C ε : ℝ}
    (hε : 0 < ε) (hf : Tendsto (fun X : ℕ => f X / X) atTop (nhds C)) :
    ∀ᶠ X : ℕ in atTop, |f X - C * X| ≤ ε * X

theorem moebiusTotient_mul_prime (p d : ℕ) (hp : p.Prime) :
    (μ (p * d) : ℝ) / Nat.totient (p * d) =
      if p ∣ d then 0 else -((μ d : ℝ) / Nat.totient d) / ((p : ℝ) - 1)

theorem norm_sum_primitive_character_Ico_le {q : ℕ}
    (hq : 1 < q) (χ : DirichletCharacter ℂ q) (hχ : χ.IsPrimitive) (M N : ℕ) :
    ‖∑ n ∈ Ico M N, χ (n : ZMod q)‖ ≤ Real.sqrt q * (1 + Real.log q)

theorem norm_sum_primitive_character_Ico_le_harmonic {q : ℕ}
    (hq : 1 < q) (χ : DirichletCharacter ℂ q) (hχ : χ.IsPrimitive) (M N : ℕ) :
    ‖∑ n ∈ Ico M N, χ (n : ZMod q)‖ ≤ Real.sqrt q * (harmonic q : ℝ)

theorem norm_sum_primitive_character_inv_Ico_le_harmonic {q : ℕ}
    (hq : 1 < q) (χ : DirichletCharacter ℂ q) (hχ : χ.IsPrimitive) (M N : ℕ) :
    ‖∑ n ∈ Ico M N, χ⁻¹ (n : ZMod q)‖ ≤ Real.sqrt q * (harmonic q : ℝ)

theorem norm_centeredCharacterPsi_le_max {q t T : ℕ}
    (χ : DirichletCharacter ℂ q) (ht : t ≤ T) :
    ‖centeredCharacterPsi t χ‖ ≤ characterMaxError T χ

theorem characterMaxError_eq_characterPsiMax_of_ne_one {q : ℕ}
    (T : ℕ) (χ : DirichletCharacter ℂ q) (hχ : χ ≠ 1) :
    characterMaxError T χ = characterPsiMax T χ

theorem primitive_characterMaxError_eq_characterPsiMax {q : ℕ}
    (hq : 1 < q) (T : ℕ) (χ : DirichletCharacter ℂ q) (hχ : χ.IsPrimitive) :
    characterMaxError T χ = characterPsiMax T χ

theorem primitiveCharacter_apply_of_primitive {r : ℕ}
    (ψ : DirichletCharacter ℂ r) (hψ : ψ.IsPrimitive) (a : ℤ) :
    ψ.primitiveCharacter a = ψ a

theorem prime_sq_dvd_mul_of_squarefree_left {p d r : ℕ}
    (hp : p.Prime) (hd : Squarefree d) (hprod : p ^ 2 ∣ d * r) :
    p ^ 2 ∣ r ∨ p ∣ d ∧ p ∣ r

theorem cauchySeq_characterDirichletPartialSum {q : ℕ}
    (hq : 1 < q) (χ : DirichletCharacter ℂ q) (hχ : χ.IsPrimitive)
    (s : ℂ) (hs : 0 < s.re) : CauchySeq (characterDirichletPartialSum χ s)

theorem differentiableOn_characterDirichletLimit {q : ℕ}
    (hq : 1 < q) (χ : DirichletCharacter ℂ q) (hχ : χ.IsPrimitive) :
    DifferentiableOn ℂ (characterDirichletLimit χ) {s : ℂ | 0 < s.re}

theorem differentiable_characterDirichletPartialSum {q : ℕ}
    (χ : DirichletCharacter ℂ q) (N : ℕ) :
    Differentiable ℂ (fun s => characterDirichletPartialSum χ s N)

theorem tendstoLocallyUniformlyOn_characterDirichletPartialSum_limit {q : ℕ}
    (hq : 1 < q) (χ : DirichletCharacter ℂ q) (hχ : χ.IsPrimitive) :
    TendstoLocallyUniformlyOn (fun N s => characterDirichletPartialSum χ s N)
      (characterDirichletLimit χ) atTop {s : ℂ | 0 < s.re}

theorem tendstoUniformlyOn_characterDirichletPartialSum_limit {q : ℕ}
    (hq : 1 < q) (χ : DirichletCharacter ℂ q) (hχ : χ.IsPrimitive)
    (δ H : ℝ) (hδ : 0 < δ) :
    TendstoUniformlyOn (fun N s => characterDirichletPartialSum χ s N)
      (characterDirichletLimit χ) atTop {s : ℂ | δ ≤ s.re ∧ ‖s‖ ≤ H}

theorem zeroFactorMultiplicity_cast {f : ℂ → ℂ} {K : Set ℂ}
    (hf : AnalyticOnNhd ℂ f K) (hK : IsCompact K) :
    (zeroFactorMultiplicity f K : ℝ) = ((∑ᶠ z, divisor f K z : ℤ) : ℝ)

theorem tendstoLocallyUniformlyOn_regularizedZetaPartialSum_limit :
    TendstoLocallyUniformlyOn (fun N s => regularizedZetaPartialSum s N)
      regularizedZetaLimit atTop {s : ℂ | 0 < s.re}

theorem tendstoLocallyUniformlyOn_regularizedZetaPartialSum_regularizedRiemannZeta :
    TendstoLocallyUniformlyOn (fun N s => regularizedZetaPartialSum s N)
      regularizedRiemannZeta atTop {s : ℂ | 0 < s.re}

theorem tendstoUniformlyOn_regularizedZetaPartialSum_limit (δ H : ℝ) (hδ : 0 < δ) :
    TendstoUniformlyOn (fun N s => regularizedZetaPartialSum s N)
      regularizedZetaLimit atTop {s : ℂ | δ ≤ s.re ∧ ‖s‖ ≤ H}

theorem characterEulerMultiplier_ne_zero_of_re_pos {M : ℕ}
    (χ : DirichletCharacter ℂ M) (N : ℕ) (s : ℂ) (hs : 0 < s.re) :
    (∏ p ∈ N.primeFactors, (1 - χ p * (p : ℂ) ^ (-s))) ≠ 0

theorem quadraticProductCoefficients_comm {Q : ℕ}
    (χ₁ χ₂ : DirichletCharacter ℂ Q) :
    quadraticProductCoefficients χ₁ χ₂ = quadraticProductCoefficients χ₂ χ₁

theorem quadraticProductCoefficients_isMultiplicative {Q : ℕ}
    (χ₁ χ₂ : DirichletCharacter ℂ Q) :
    (quadraticProductCoefficients χ₁ χ₂).IsMultiplicative

theorem quadratic_character_mul_ne_one_of_ne {q : ℕ}
    (χ₁ χ₂ : DirichletCharacter ℂ q) (hχ₁ : χ₁ ^ 2 = 1) (hne : χ₁ ≠ χ₂) :
    χ₁ * χ₂ ≠ 1

theorem norm_character_sum_Ioc_interval_le_length {q : ℕ}
    (χ : DirichletCharacter ℂ q) (M N : ℕ) :
    ‖∑ n ∈ Ioc M N, χ (n : ZMod q)‖ ≤ (N - M : ℕ)

theorem norm_character_sum_Ioc_le_length {q : ℕ}
    (χ : DirichletCharacter ℂ q) (N : ℕ) :
    ‖∑ n ∈ Ioc 0 N, χ (n : ZMod q)‖ ≤ (N : ℝ)

theorem LSeriesSummable_characterArithmeticFunction {q : ℕ}
    (χ : DirichletCharacter ℂ q) {s : ℂ} (hs : 1 < s.re) :
    LSeriesSummable (toArithmeticFunction (χ ·)) s

theorem norm_character_reciprocal_partialSum_le_one_add_log {q : ℕ}
    (χ : DirichletCharacter ℂ q) (M : ℕ) :
    ‖powerDirichletPartialSum (toArithmeticFunction (χ ·)) 1 M‖ ≤ 1 + Real.log M

theorem primitiveLogZeroFreeWidth_le_one_div_log {q : ℕ}
    (hq : 1 < q) (t : ℝ) :
    primitiveLogZeroFreeWidth q t ≤ 1 / Real.log q

theorem primitiveLogZeroFreeWidth_antitone_abs (q : ℕ) {t H : ℝ}
    (ht : |t| ≤ |H|) :
    primitiveLogZeroFreeWidth q H ≤ primitiveLogZeroFreeWidth q t

theorem initialIntervalSup_mono (f : ℝ → ℝ) {a x y : ℝ}
    (hax : a ≤ x) (hxy : x ≤ y) (hbdd : BddAbove (f '' Icc a y)) :
    initialIntervalSup f a x ≤ initialIntervalSup f a y

theorem le_initialIntervalSup (f : ℝ → ℝ) {a t x : ℝ}
    (hbdd : BddAbove (f '' Icc a x)) (ht : t ∈ Icc a x) :
    f t ≤ initialIntervalSup f a x

theorem card_sifted_eq_twin (x z : ℕ) (hz : 3 ≤ z) (hxz : x + 2 < z * z) :
    #{n ∈ range (x + 1) | Nat.Coprime (primorial z) (n * (n + 2))}
      = #{n ∈ range (x + 1) | z < n ∧ n.Prime ∧ (n + 2).Prime}
